          <div class="ob-actions"><button class="ob-btn primary" type="submit">Uložit a pokračovat →</button></div>
        </form>
      <?php else: ?>
        <div class="ob-feature"><span><?= $target==='nia'?'✦':'✓' ?></span><div><b><?= $target==='nia'?'Nia je součástí aplikace, ne položka menu.':'Všechno zůstává propojené.' ?></b><small><?= $target==='nia'?'Může sama upozornit na úkoly, splatnosti, platby nebo další věci, které dávají smysl řešit.':'Od zákazníka přes zakázku až po fakturu, banku a finance.' ?></small></div></div>
        <div class="ob-actions"><div><?php if($prev): ?><a class="ob-btn" href="<?=$prev?>">← Zpět</a><?php endif; ?></div><?php if($next): ?><a class="ob-btn primary" href="<?=$next?>">Pokračovat →</a><?php else: ?><form method="post" action="/uvod/complete"><input type="hidden" name="_csrf" value="<?=View::e(App\Core\Auth::csrf())?>"><button class="ob-btn primary" type="submit">Dokončit a otevřít Byznio →</button></form><?php endif; ?></div>
      <?php endif; ?>
